def smallest_change(arr):
    def is_palindrome(sub_arr):
        return sub_arr == sub_arr[::-1]

    def min_changes_to_palindrome(sub_arr):
        changes = 0
        for i in range(len(sub_arr) // 2):
            changes += abs(sub_arr[i] - sub_arr[-i - 1])
        return changes

    if not arr:
        return 0

    middle = len(arr) // 2
    left_sub_arr = arr[:middle]
    right_sub_arr = arr[middle + len(arr) % 2:]

    if is_palindrome(arr):
        return 0

    return min_changes_to_palindrome(left_sub_arr) + min_changes_to_palindrome(right_sub_arr)

